import{_ as o,o as d,c,a2 as i}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"开发规范","description":"","frontmatter":{},"headers":[],"relativePath":"guide/conventions.md","filePath":"guide/conventions.md"}'),a={name:"guide/conventions.md"};function t(l,e,r,n,s,u){return d(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="开发规范" tabindex="-1">开发规范 <a class="header-anchor" href="#开发规范" aria-label="Permalink to &quot;开发规范&quot;">​</a></h1><p>遵循以下约定可避免最常见的集成问题。</p><h2 id="单位与坐标" tabindex="-1">单位与坐标 <a class="header-anchor" href="#单位与坐标" aria-label="Permalink to &quot;单位与坐标&quot;">​</a></h2><ul><li>位置、宽高、边距、间距：<strong>mm</strong>；字号：<strong>pt</strong>；旋转：<strong>度</strong>（顺时针，绕元素中心）。</li><li>坐标原点为页面左上角，y 向下。</li><li>代码中写坐标保留最多 2 位小数，消除浮点残差。</li></ul><h2 id="数据流" tabindex="-1">数据流 <a class="header-anchor" href="#数据流" aria-label="Permalink to &quot;数据流&quot;">​</a></h2><ol><li><strong>模板与数据分离</strong>：模板 JSON 持久化（服务端 / localStorage）；每次打印注入 <code>input</code>，绝不把业务数据写进模板。</li><li><strong>快照只读</strong>：<code>document.data</code>、句柄 <code>data</code>、事件 payload 都是快照或内部引用，只读使用；修改一律走实例方法。</li><li><strong>显式输入</strong>：<code>toHTML({})</code> 表示空输入，不会自动合并示例数据；需要示例数据就省略 <code>input</code> 参数。</li><li><strong>数组属性整体提交</strong>：更新 <code>columns</code>、<code>rows</code>、<code>points</code> 时提交新数组，不做就地 push。</li></ol><h2 id="资源与生命周期" tabindex="-1">资源与生命周期 <a class="header-anchor" href="#资源与生命周期" aria-label="Permalink to &quot;资源与生命周期&quot;">​</a></h2><ul><li><code>createPrintStudio()</code> / <code>createPrintRenderer()</code> 的实例用完必须 <code>dispose()</code>，放在 <code>finally</code> 中；<code>await print()</code> 返回（打印对话框已调起）后再 <code>dispose</code> 是安全的。含 <code>await print()</code> 的流程同样在 <code>finally</code> 中释放即可。</li><li><code>preview()</code> 返回的 <code>PreviewHandle</code> 在不再展示时调用 <code>close()</code>；预览窗口未关闭前不要 <code>dispose()</code> 实例。</li><li><code>events.on</code> / <code>state.subscribe</code> / <code>errors.addRule</code> 返回解绑函数，按订阅生命周期调用。</li><li>Vue 中优先 <code>usePrintStudio()</code>（随作用域自动清理）；跨路由、跨页面复用的实例用 <code>createPrintStudio()</code> 创建并自行管理。</li></ul><h2 id="错误处理" tabindex="-1">错误处理 <a class="header-anchor" href="#错误处理" aria-label="Permalink to &quot;错误处理&quot;">​</a></h2><ul><li>实例方法调用失败由调用方接 Promise；统一上报经 <code>studio.errors</code>（<code>capture</code> 记录、<code>addRule</code> 定制规则）。</li><li>输出 <code>warnings</code> 必须检查：绑定取值失败、资源加载失败不中断输出，但会体现在 warnings 中。</li><li>领域错误类型为 <code>DesignerException</code>（<code>@printstack/print-studio/core</code>），按 <code>error.code</code> 分支。</li><li>外部异步失败调用 <code>studio.errors.capture(error, context)</code>，交由统一错误处理展示，不要在业务代码中静默丢弃。</li></ul><h2 id="事件使用" tabindex="-1">事件使用 <a class="header-anchor" href="#事件使用" aria-label="Permalink to &quot;事件使用&quot;">​</a></h2><ul><li>刷新按钮状态优先 <code>state.subscribe()</code>（同步、轻量）；需要动作 payload 才用事件总线。</li><li>订阅不回放当前值：先读状态再监听。</li><li>事件回调保持轻量；远端保存由业务层防抖。</li><li>撤销 / 加载不重放元素事件；维护文档镜像监听 <code>document:changed</code> 并整体读取快照。</li></ul><h2 id="模板-json-管理" tabindex="-1">模板 JSON 管理 <a class="header-anchor" href="#模板-json-管理" aria-label="Permalink to &quot;模板 JSON 管理&quot;">​</a></h2><ul><li>版本字段：<code>version</code> 当前 <code>&#39;1.0&#39;</code>；加载外部 JSON 用 <code>deserializeDocument</code> 检查 <code>skippedTypes</code>。</li><li>保存前后不做格式假设；JSON 即序列化结果，不要手工重组结构。</li><li>重命名数据源 key 后同步更新表达式 / 表格绑定 / 循环 <code>collection</code>。</li></ul><h2 id="扩展" tabindex="-1">扩展 <a class="header-anchor" href="#扩展" aria-label="Permalink to &quot;扩展&quot;">​</a></h2><ul><li>新元素类型走 <code>ElementDefinition</code> 注册，不在业务代码里按 <code>type</code> 写分支渲染。</li><li>界面扩展（按钮 / 面板 / 命令 / 菜单项）通过插件系统接入：<code>definePlugin()</code> 声明权限与清单，<code>setup</code> 中经 <code>commands</code> / <code>events</code> / <code>panels</code> / <code>menu</code> 等公开入口注册能力。</li><li>自定义字体在 <code>rendering.fonts</code> 声明，<code>fontFamily</code> 与 <code>family</code> 精确匹配，粗体提供对应字重文件。</li></ul>',16)])])}const m=o(a,[["render",t]]);export{p as __pageData,m as default};
